1	<script>
2	    import { tick } from 'svelte';
3	
4	    let { item, onRemoveItem } = $props();
5	
6	    let editing = $state(false);
7	
8	    function startEdit() {
9	        editing = true;
10	    }
11	
12	    function handleEdit(event) {
13	        if (event.key === "Enter")
14	            event.target.blur();
15	        else if (event.key === "Escape")
16	            editing = false;
17	    }
18	
19	    function updateItem(event) {
20	        if (!editing) return;
21	        const { value } = event.target;
22	        if (value.length) {
23	            item.description = value;
24	        } else {
25	            onRemoveItem();
26	        }
27	        editing = false;
28	    }
29	
30	    async function focusInput(element) {
31	        await tick();
32	        element.focus();
33	    }
34	</script>
35	
36	<li class:completed={item.completed} class:editing>
37	    <div class="view">
38	        <input class="toggle" type="checkbox" onchange={(event) => item.completed = event.target.checked} checked={item.completed} />
39	        <!-- svelte-ignore a11y_label_has_associated_control -->
40	        <label ondblclick={startEdit}>{item.description}</label>
41	        <button onclick={onRemoveItem} class="destroy" aria-label="Delete"></button>
42	    </div>
43	
44	    {#if editing}
45	        <input
46	            value={item.description}
47	            class="edit"
48	            aria-label="Edit todo"
49	            onkeydown={handleEdit}
50	            onblur={updateItem}
51	            use:focusInput
52	        />
53	    {/if}
54	</li>
55

1	<script>
2	    import { router } from './router.js';
3	
4	    import Header from './Header.svelte';
5	    import Footer from './Footer.svelte';
6	    import Item from './Item.svelte';
7	
8	    import "./app.css";
9	    import "todomvc-app-css/index.css";
10	    import "todomvc-common/base.css";
11	
12	    let currentFilter = $state("all");
13	    let items = $state([]);
14	
15	    function addItem(text) {
16	        items.push({
17	            id: crypto.randomUUID(), // This only works in secure-context.
18	            description: text,
19	            completed: false,
20	        });
21	    }
22	
23	    function removeItem(id) {
24	        const index = items.findIndex((item) => item.id === id);
25	        if (index !== -1) items.splice(index, 1);
26	    }
27	
28	    function toggleAllItems(event) {
29	        const checked = event.target.checked;
30	        for (const item of items) {
31	            item.completed = checked;
32	        }
33	    }
34	
35	    function removeCompletedItems() {
36	        items = items.filter((item) => !item.completed);
37	    }
38	
39	    $effect(() => {
40	        router((route) => (currentFilter = route)).init();
41	    });
42	
43	    const filtered = $derived(
44	        currentFilter === "all"
45	            ? items
46	            : currentFilter === "completed"
47	                ? items.filter((item) => item.completed)
48	                : items.filter((item) => !item.completed)
49	    );
50	    const numActive = $derived(items.filter((item) => !item.completed).length);
51	    const numCompleted = $derived(items.filter((item) => item.completed).length);
52	</script>
53	
54	<Header onAddItem={addItem} />
55	
56	<main class="main" hidden={items.length === 0}>
57	    <div class="toggle-all-container">
58	        <input id="toggle-all" class="toggle-all" type="checkbox" onchange={toggleAllItems} checked={items.length > 0 && numCompleted === items.length} />
59	        <label for="toggle-all">Mark all as complete</label>
60	    </div>
61	    <ul class="todo-list">
62	        {#each filtered as item (item.id)}
63	            <Item {item} onRemoveItem={() => removeItem(item.id)} />
64	        {/each}
65	    </ul>
66	</main>
67	
68	<Footer {numActive} {currentFilter} {numCompleted} onRemoveCompletedItems={removeCompletedItems} hidden={items.length === 0} />
